// Generate tests/fixtures/schedules.sexp from QuantLib's Schedule and
// ActualActual(ISMA).
//
//   nix develop .#fixtures -c sh tests/fixtures/generate.sh
//
// Each case is a plist: the Schedule's inputs, then either :error "message"
// (QuantLib refused them) or :dates (adjusted), :regular (one flag per
// period), :icma (ActualActual(ISMA, schedule) of each period, or NIL if
// QuantLib refused or returned a non-finite value, as for periods over two
// years, which imply 0 coupons a year) and :icma-reference (ActualActual(ISMA) of each period
// with the period itself as reference period).

#include <ql/quantlib.hpp>

#include <cmath>
#include <cstdio>
#include <string>
#include <utility>
#include <vector>

using namespace QuantLib;

namespace {

std::string iso(const Date& d) {
    char buffer[16];
    std::snprintf(buffer, sizeof buffer, "%04d-%02d-%02d", d.year(), int(d.month()),
                  d.dayOfMonth());
    return buffer;
}

Date parse(const std::string& s) {
    return Date(std::stoi(s.substr(8, 2)), Month(std::stoi(s.substr(5, 2))),
                std::stoi(s.substr(0, 4)));
}

struct Shape {
    std::string effective, termination, tenor, first, nextToLast;
};

Period parsePeriod(const std::string& s) {
    int n = std::stoi(s.substr(0, s.size() - 1));
    switch (s.back()) {
      case 'D': return Period(n, Days);
      case 'W': return Period(n, Weeks);
      case 'M': return Period(n, Months);
      default: return Period(n, Years);
    }
}

const char* conventionName(BusinessDayConvention c) {
    switch (c) {
      case Following: return ":following";
      case ModifiedFollowing: return ":modified-following";
      case Preceding: return ":preceding";
      case ModifiedPreceding: return ":modified-preceding";
      default: return ":unadjusted";
    }
}

const char* ruleName(DateGeneration::Rule r) {
    switch (r) {
      case DateGeneration::Backward: return ":backward";
      case DateGeneration::Forward: return ":forward";
      case DateGeneration::Zero: return ":zero";
      default: return ":twentieth";
    }
}

}

int main(int argc, char** argv) {
    if (argc != 2) {
        std::fprintf(stderr, "usage: %s output.sexp\n", argv[0]);
        return 1;
    }
    FILE* out = std::fopen(argv[1], "w");
    std::fprintf(out, ";;;; schedules.sexp --- generated by tests/fixtures/generate.sh from "
                      "QuantLib %s\n", QL_VERSION);
    std::vector<std::pair<std::string, Calendar>> calendars = {
        {"target", TARGET()},
        {"united-states-settlement", UnitedStates(UnitedStates::Settlement)},
        {"nyse", UnitedStates(UnitedStates::NYSE)},
        {"united-states-government-bond", UnitedStates(UnitedStates::GovernmentBond)},
        {"united-kingdom-settlement", UnitedKingdom(UnitedKingdom::Settlement)},
        {"united-kingdom-exchange", UnitedKingdom(UnitedKingdom::Exchange)}};
    std::vector<Shape> shapes = {
        // month-end, regular
        {"2024-01-31", "2029-01-31", "6M", "", ""},
        // odd start: short front under :backward, short back under :forward
        {"2024-03-15", "2029-01-31", "6M", "", ""},
        // explicit first date: a short front period
        {"2024-03-15", "2029-01-31", "6M", "2024-07-31", ""},
        // explicit first date off the grid: a long front period
        {"2024-01-31", "2029-01-31", "6M", "2024-12-31", ""},
        // explicit next-to-last date: a long back period
        {"2024-01-31", "2029-03-15", "6M", "", "2028-07-31"},
        // explicit next-to-last date: a short back period
        {"2024-01-31", "2029-03-15", "6M", "", "2029-01-31"},
        // February month ends, quarterly
        {"2023-02-28", "2026-08-31", "3M", "", ""},
        // leap day, annual
        {"2024-02-29", "2030-02-28", "1Y", "", ""},
        // monthly over a year, starting on the 30th
        {"2025-04-30", "2026-04-30", "1M", "", ""}};
    std::vector<BusinessDayConvention> conventions = {ModifiedFollowing, Following};
    int count = 0;
    auto emit = [&](const std::string& calendarName, const Calendar& calendar, const Shape& shape,
                    BusinessDayConvention convention, BusinessDayConvention terminationConvention,
                    DateGeneration::Rule rule, bool eom) {
        std::fprintf(out, "(:calendar \"%s\" :effective \"%s\" :termination \"%s\" :tenor \"%s\""
                          " :convention %s :termination-convention %s :rule %s"
                          " :end-of-month %s :first-date %s%s%s :next-to-last-date %s%s%s",
                     calendarName.c_str(), shape.effective.c_str(), shape.termination.c_str(),
                     shape.tenor.c_str(), conventionName(convention),
                     conventionName(terminationConvention), ruleName(rule), eom ? "t" : "nil",
                     shape.first.empty() ? "nil" : "\"", shape.first.c_str(),
                     shape.first.empty() ? "" : "\"",
                     shape.nextToLast.empty() ? "nil" : "\"", shape.nextToLast.c_str(),
                     shape.nextToLast.empty() ? "" : "\"");
        try {
            Schedule s(parse(shape.effective), parse(shape.termination), parsePeriod(shape.tenor),
                       calendar, convention, terminationConvention, rule, eom,
                       shape.first.empty() ? Date() : parse(shape.first),
                       shape.nextToLast.empty() ? Date() : parse(shape.nextToLast));
            std::fprintf(out, "\n :dates (");
            for (const Date& d : s.dates())
                std::fprintf(out, " \"%s\"", iso(d).c_str());
            std::fprintf(out, ")\n :regular (");
            for (Size i = 1; i < s.size(); ++i)
                std::fprintf(out, " %s", s.isRegular(i) ? "t" : "nil");
            std::fprintf(out, ")\n :icma ");
            try {
                ActualActual icma(ActualActual::ISMA, s);
                std::string values = "(";
                for (Size i = 0; i + 1 < s.size(); ++i) {
                    char buffer[40];
                    Real value = icma.yearFraction(s.date(i), s.date(i + 1));
                    if (!std::isfinite(value))
                        throw std::runtime_error("non-finite ICMA year fraction");
                    std::snprintf(buffer, sizeof buffer, " %.17gd0", value);
                    values += buffer;
                }
                std::fprintf(out, "%s)", values.c_str());
            } catch (std::exception&) {
                std::fprintf(out, "nil");
            }
            std::fprintf(out, "\n :icma-reference (");
            ActualActual old(ActualActual::ISMA);
            for (Size i = 0; i + 1 < s.size(); ++i)
                std::fprintf(out, " %.17gd0",
                             old.yearFraction(s.date(i), s.date(i + 1), s.date(i), s.date(i + 1)));
            std::fprintf(out, "))\n");
        } catch (std::exception& e) {
            std::string message = e.what();
            for (auto& c : message)
                if (c == '"' || c == '\\' || c == '\n') c = ' ';
            std::fprintf(out, "\n :error \"%s\")\n", message.c_str());
        }
        ++count;
    };
    for (const auto& [name, calendar] : calendars)
        for (Size k = 0; k < shapes.size(); ++k)
            for (DateGeneration::Rule rule : {DateGeneration::Backward, DateGeneration::Forward})
                for (bool eom : {false, true}) {
                    BusinessDayConvention convention = conventions[k % 2];
                    BusinessDayConvention termination = (k % 3 == 0) ? Unadjusted : convention;
                    emit(name, calendar, shapes[k], convention, termination, rule, eom);
                }
    // Zero and twentieth rules, on the first two shapes.
    for (const auto& [name, calendar] : calendars)
        for (Size k = 0; k < 2; ++k) {
            emit(name, calendar, shapes[k], ModifiedFollowing, ModifiedFollowing,
                 DateGeneration::Zero, false);
            Shape quarterly = shapes[k];
            quarterly.tenor = "3M";
            emit(name, calendar, quarterly, Following, Following, DateGeneration::Twentieth,
                 false);
        }
    std::fclose(out);
    std::fprintf(stderr, "wrote %d schedules to %s\n", count, argv[1]);
    return 0;
}
